<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { RefreshCwIcon } from '@lucide/vue'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription } from '@/components/ui/dialog'
import { Tabs,TabsList,TabsTrigger } from '@/components/ui/tabs'
import { Select,SelectTrigger,SelectValue,SelectContent,SelectGroup,SelectItem } from '@/components/ui/select'
import { knowledgeTruncated,knowledgeErrors,knowledgeDocs,knowledgeOpen,knowledgeTab,loadKnowledge,liveKnowledge,resolveKnowledge,linkProblem,type KnowledgeDoc } from '@/services/knowledge'
import { useWorkbench } from '@/stores/workbench'
import { message } from '@/services/api'
const store=useWorkbench(),loading=ref(false),error=ref(''),query=ref(''),graphMode=ref('workspace')
const docs=computed(()=>{void knowledgeDocs.value;return liveKnowledge()}),active=computed(()=>docs.value.find(d=>d.workspaceId===store.active?.workspaceId&&d.path===store.active.path))
const backlinks=computed(()=>active.value?docs.value.filter(d=>d.links.some(l=>resolveKnowledge(d,l.target,l.wiki)?.path===active.value?.path&&d.workspaceId===active.value!.workspaceId)):[])
const related=computed(()=>active.value?docs.value.filter(d=>d.path!==active.value!.path||d.workspaceId!==active.value!.workspaceId).map(d=>({doc:d,score:d.tags.filter(t=>active.value!.tags.includes(t)).length+(backlinks.value.includes(d)?2:0)+(active.value!.links.some(l=>resolveKnowledge(active.value!,l.target,l.wiki)?.path===d.path&&d.workspaceId===active.value!.workspaceId)?2:0)})).filter(d=>d.score).sort((a,b)=>b.score-a.score).map(x=>x.doc):[])
const broken=computed(()=>docs.value.flatMap(d=>d.links.map(l=>({doc:d,link:l,problem:linkProblem(d,l)})).filter(x=>x.problem)))
const graphDocs=computed(()=>graphMode.value==='current'&&active.value?docs.value.filter(d=>(d.workspaceId===active.value!.workspaceId&&d.path===active.value!.path)||backlinks.value.some(x=>x.workspaceId===d.workspaceId&&x.path===d.path)||active.value!.links.some(l=>{const target=resolveKnowledge(active.value!,l.target,l.wiki);return target?.workspaceId===d.workspaceId&&target.path===d.path})):active.value?docs.value.filter(d=>d.workspaceId===active.value!.workspaceId):docs.value)
const nodes=computed(()=>graphDocs.value.slice(0,120).map((d,i,a)=>({doc:d,x:300+235*Math.cos(i*2*Math.PI/a.length),y:260+200*Math.sin(i*2*Math.PI/a.length)})))
const edges=computed(()=>nodes.value.flatMap(n=>n.doc.links.flatMap(l=>{const target=resolveKnowledge(n.doc,l.target,l.wiki);const to=nodes.value.find(x=>x.doc===target);return to?[{from:n,to}]:[]})))
async function refresh(){loading.value=true;error.value='';try{await loadKnowledge(true)}catch(e){error.value=message(e)}finally{loading.value=false}}
watch(knowledgeOpen,open=>{if(open){if(!['backlinks','related','broken','graph'].includes(knowledgeTab.value))knowledgeTab.value='backlinks';void refresh()}})
async function open(d:KnowledgeDoc){await store.open(d.workspaceId,d.path);knowledgeOpen.value=false}
</script>
<template><Dialog v-model:open="knowledgeOpen"><DialogContent class="flex h-[min(800px,90dvh)] flex-col sm:max-w-5xl"><DialogHeader><DialogTitle>工作区知识与文档</DialogTitle><DialogDescription>浏览文档、标签与链接关系。索引只读取本地 Markdown 文件。</DialogDescription></DialogHeader><Tabs v-model="knowledgeTab"><TabsList class="flex h-auto flex-wrap"><TabsTrigger value="backlinks">反向链接</TabsTrigger><TabsTrigger value="related">相关文档</TabsTrigger><TabsTrigger value="broken">断链检查</TabsTrigger><TabsTrigger value="graph">关系图</TabsTrigger></TabsList></Tabs><div class="flex gap-2"><Input v-model="query" aria-label="筛选文档" placeholder="搜索文件名或标签…"/><Button variant="outline" size="icon" class="shrink-0" aria-label="刷新文档列表" title="刷新文档列表" :disabled="loading" :aria-busy="loading" @click="refresh"><RefreshCwIcon :class="{ 'animate-spin': loading }"/></Button></div><p v-if="loading" role="status">正在读取本地文档…</p><p v-if="error" role="alert" class="text-sm text-destructive">{{error}}</p><p v-if="knowledgeTruncated" class="text-xs text-muted-foreground">部分大文件或超出索引上限的文档未加载；当前结果不代表完整工作区。</p><p v-for="problem in knowledgeErrors" :key="problem" role="alert" class="text-xs text-destructive">{{problem}}</p><div class="min-h-0 flex-1 overflow-auto">
<template v-if="knowledgeTab==='backlinks'||knowledgeTab==='related'"><p class="mb-3 text-sm text-muted-foreground">{{active?.path||'请先打开文档'}} · {{knowledgeTab==='backlinks'?'哪些文档引用了当前文档':'按共同标签与链接关联排列'}}</p><Button v-for="d in knowledgeTab==='backlinks'?backlinks:related" :key="d.workspaceId+d.path" variant="ghost" class="w-full justify-start" @click="open(d)">{{d.path}}</Button><p v-if="!(knowledgeTab==='backlinks'?backlinks:related).length" class="text-sm text-muted-foreground">暂无关联文档。</p></template>
<template v-else-if="knowledgeTab==='broken'"><p v-if="!broken.length" class="text-sm text-primary">没有发现失效文档或章节链接。</p><Button v-for="(row,i) in broken" :key="i" variant="ghost" class="h-auto w-full flex-col items-start gap-1 py-3" @click="open(row.doc)"><span>{{row.doc.path}} → {{row.link.target}}</span><span class="text-xs text-destructive">{{row.problem}}</span></Button></template>
<template v-else-if="knowledgeTab==='graph'"><div class="mb-3 flex items-center justify-between gap-3"><p class="text-xs text-muted-foreground">显示前 120 篇文档，点击节点打开文档。</p><Select v-model="graphMode"><SelectTrigger aria-label="关系图范围" class="shrink-0"><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectItem value="workspace">当前工作区</SelectItem><SelectItem value="current">当前文档及直接关联</SelectItem></SelectGroup></SelectContent></Select></div><svg viewBox="0 0 600 520" class="mx-auto w-full max-w-3xl"><line v-for="(e,i) in edges" :key="i" :x1="e.from.x" :y1="e.from.y" :x2="e.to.x" :y2="e.to.y" class="stroke-border"/><g v-for="n in nodes" :key="n.doc.workspaceId+n.doc.path" role="button" tabindex="0" :aria-label="n.doc.path" class="cursor-pointer" @click="open(n.doc)" @keydown.enter="open(n.doc)"><title>{{n.doc.path}}</title><circle :cx="n.x" :cy="n.y" r="7" class="fill-primary"/><text :x="n.x+10" :y="n.y+4" class="fill-foreground text-[9px]">{{n.doc.path.split('/').pop()}}</text></g></svg></template>
</div></DialogContent></Dialog></template>
